        }

for rec in records:
    if rec.x_studio_bike:
        action = {
            'type': 'ir.actions.act_window',
            'res_model': 'x_bikes',
            'res_id': rec.x_studio_bike.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    if rec.x_studio_date and rec.x_studio_lease_plan:
        plan = rec.x_studio_lease_plan
        start_date = rec.x_studio_date
        duration = plan.x_studio_lease_duration or 1
        unit = plan.x_studio_duration_unit or 'Months'

        # Calculate End Date
        if unit == 'Days':
            end_date = start_date + datetime.timedelta(days=duration)
        elif unit == 'Weeks':
            end_date = start_date + datetime.timedelta(days=7 * duration)
        elif unit == 'Years':
            end_date = start_date + dateutil.relativedelta.relativedelta(years=duration)
        else:  # Months
            end_date = start_date + dateutil.relativedelta.relativedelta(months=duration)

        rec.write({'x_studio_end_date': end_date})

        # Generate Installment Schedule ONLY if contract is Active and Security Deposit is paid
        inv = rec.x_studio_deposit_invoice_id
        is_paid = bool(inv and inv.payment_state in ('paid', 'in_payment'))
        if rec.x_studio_selection_1 == 'Active' and is_paid:
            if not rec.x_studio_installment_ids or any(i.x_studio_status == 'Draft' for i in rec.x_studio_installment_ids):
                rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_status == 'Draft').unlink()

                freq = plan.x_studio_payment_frequency or 'Monthly'
                current_date = start_date
                idx = 1

                while current_date < end_date:
                    env['x_lease_installment'].create({
                        'x_name': f"Installment #{idx}",
                        'x_studio_contract_id': rec.id,
                        'x_studio_date': current_date,
                        'x_studio_amount': plan.x_studio_value or 0.0,
                        'x_studio_status': 'Draft',
                        'x_studio_currency_id': plan.x_studio_currency_id.id if plan.x_studio_currency_id else False,
                    })
                    idx += 1
                    if freq == 'Daily':
                        current_date += datetime.timedelta(days=1)
                    elif freq == 'Weekly':
                        current_date += datetime.timedelta(days=7)
                    elif freq == 'Quarterly':
                        current_date += dateutil.relativedelta.relativedelta(months=3)
                    elif freq == 'Yearly':
                        current_date += dateutil.relativedelta.relativedelta(years=1)
                    else:  # Monthly
                        current_date += dateutil.relativedelta.relativedelta(months=1)

for rec in records:
    draft_installments = rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_status == 'Draft')
    if not draft_installments:
        raise UserError("All installments for this lease contract have already been invoiced.")

    installments_to_invoice = draft_installments[:1]
    created_move = False
    if not installments_to_invoice and not rec.x_studio_installment_ids:
        amount = rec.x_studio_lease_plan.x_studio_value if rec.x_studio_lease_plan else 0.0
        created_move = env['account.move'].create({
            'move_type': 'out_invoice',
            'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'invoice_date': datetime.date.today(),
            'invoice_line_ids': [(0, 0, {
                'name': f"Lease Contract Payment - {rec.x_name}",
                'quantity': 1,
                'price_unit': amount,
            })],
        })
    all_past_invoices = rec.x_studio_installment_ids.mapped('x_studio_invoice_id').filtered(
        lambda inv: inv and inv.state != 'cancel' and inv.payment_state not in ('paid', 'in_payment')
    )
    if rec.x_studio_deposit_invoice_id and rec.x_studio_deposit_invoice_id.state != 'cancel' and rec.x_studio_deposit_invoice_id.payment_state not in ('paid', 'in_payment'):
        all_past_invoices |= rec.x_studio_deposit_invoice_id

    invoice_lines = []
    for old_inv in all_past_invoices:
        for line in old_inv.invoice_line_ids:
            line_name = line.name or "Arrears Line"
            if not line_name.startswith("Arrears:"):
                line_name = f"Arrears: {line_name}"
            invoice_lines.append((0, 0, {
                'name': line_name,
                'quantity': line.quantity or 1,
                'price_unit': line.price_unit,
            }))

    for inst in installments_to_invoice:
        invoice_lines.append((0, 0, {
            'name': f"Lease Installment - {rec.x_name} ({inst.x_name})",
            'quantity': 1,
            'price_unit': inst.x_studio_amount,
        }))
        late_fee = inst.x_studio_late_fee_amount or 0.0
        if late_fee > 0:
            invoice_lines.append((0, 0, {
                'name': f"Late Payment Penalty Fee - {rec.x_name} ({inst.x_name})",
                'quantity': 1,
                'price_unit': late_fee,
            }))

    created_move = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
        'invoice_date': datetime.date.today(),
        'invoice_line_ids': invoice_lines,
    })

    for inst in installments_to_invoice:
        inst.write({
            'x_studio_invoice_id': created_move.id,
            'x_studio_status': 'Invoiced',
        })

    for past_inst in rec.x_studio_installment_ids.filtered(lambda i: i.x_studio_invoice_id in all_past_invoices):
        past_inst.write({'x_studio_invoice_id': created_move.id})

    if rec.x_studio_deposit_invoice_id in all_past_invoices:
        rec.write({'x_studio_deposit_invoice_id': created_move.id})

    for old_inv in all_past_invoices:
        try:
            if old_inv.state == 'posted':
                old_inv.button_draft()
            old_inv.button_cancel()
        except Exception:
            old_inv.write({'state': 'cancel'})

    if created_move:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Customer Invoice',
            'res_model': 'account.move',
            'res_id': created_move.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    target_invoice = rec.x_studio_deposit_invoice_id
    if not target_invoice and rec.x_studio_lease_plan:
        plan = rec.x_studio_lease_plan
        amt = plan.x_studio_security_deposit or 0.0
        if amt <= 0:
            amt = plan.x_studio_value or 0.0

        target_invoice = env['account.move'].create({
            'move_type': 'out_invoice',
            'partner_id': rec.x_studio_partner_id.id if rec.x_studio_partner_id else False,
            'invoice_date': datetime.date.today(),
            'invoice_line_ids': [(0, 0, {
                'name': f"Security Deposit - Contract {rec.x_name}",
                'quantity': 1,
                'price_unit': amt,
            })],
        })
        rec.write({'x_studio_deposit_invoice_id': target_invoice.id})

    if target_invoice:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Security Deposit Invoice',
            'res_model': 'account.move',
            'res_id': target_invoice.id,
            'view_mode': 'form',
            'target': 'current',
        }

for rec in records:
    invoices = rec.x_studio_installment_ids.mapped('x_studio_invoice_id')
    if rec.x_studio_deposit_invoice_id:
        invoices |= rec.x_studio_deposit_invoice_id
    if rec.x_studio_return_invoice_id:
        invoices |= rec.x_studio_return_invoice_id
    action = {
        'type': 'ir.actions.act_window',
        'name': 'Customer Invoices',
        'res_model': 'account.move',
        'view_mode': 'list,form',
        'domain': [('id', 'in', invoices.ids)],
    }
    if len(invoices) == 1:
        action['res_id'] = invoices.id
        action['view_mode'] = 'form'

for rec in records:
    contracts = env['x_lease_contract'].search(['|', ('x_studio_deposit_invoice_id', '=', rec.id), ('x_studio_return_invoice_id', '=', rec.id)])
    if not contracts:
        installments = env['x_lease_installment'].search([('x_studio_invoice_id', '=', rec.id)])
        contracts = installments.mapped('x_studio_contract_id')

    action = {
        'type': 'ir.actions.act_window',
        'name': 'Lease Contract',
        'res_model': 'x_lease_contract',
        'view_mode': 'list,form',
        'domain': [('id', 'in', contracts.ids)],
    }
    if len(contracts) == 1:
        action['res_id'] = contracts.id
        action['view_mode'] = 'form'

for rec in records:
    if rec.x_studio_invoice_id:
        action = {
            'type': 'ir.actions.act_window',
            'name': 'Customer Invoice',
            'res_model': 'account.move',
            'res_id': rec.x_studio_invoice_id.id,
            'view_mode': 'form',
            'target': 'current',
        }
